-- SHA-512 (FIPS 180-4) in pure Lua on bit32, with 64-bit words kept as (high, low) pairs of 32-bit numbers.
-- The constants were generated by tools/dev/sha512-constants.mjs with exact integer arithmetic.
local band, bor, bxor, bnot = bit32.band, bit32.bor, bit32.bxor, bit32.bnot
local rshift, lshift = bit32.rshift, bit32.lshift
local sbyte, schar, srep, sformat = string.byte, string.char, string.rep, string.format
local floor = math.floor
local MOD = 4294967296

local Kh = {
  0x428a2f98, 0x71374491, 0xb5c0fbcf, 0xe9b5dba5,
  0x3956c25b, 0x59f111f1, 0x923f82a4, 0xab1c5ed5,
  0xd807aa98, 0x12835b01, 0x243185be, 0x550c7dc3,
  0x72be5d74, 0x80deb1fe, 0x9bdc06a7, 0xc19bf174,
  0xe49b69c1, 0xefbe4786, 0x0fc19dc6, 0x240ca1cc,
  0x2de92c6f, 0x4a7484aa, 0x5cb0a9dc, 0x76f988da,
  0x983e5152, 0xa831c66d, 0xb00327c8, 0xbf597fc7,
  0xc6e00bf3, 0xd5a79147, 0x06ca6351, 0x14292967,
  0x27b70a85, 0x2e1b2138, 0x4d2c6dfc, 0x53380d13,
  0x650a7354, 0x766a0abb, 0x81c2c92e, 0x92722c85,
  0xa2bfe8a1, 0xa81a664b, 0xc24b8b70, 0xc76c51a3,
  0xd192e819, 0xd6990624, 0xf40e3585, 0x106aa070,
  0x19a4c116, 0x1e376c08, 0x2748774c, 0x34b0bcb5,
  0x391c0cb3, 0x4ed8aa4a, 0x5b9cca4f, 0x682e6ff3,
  0x748f82ee, 0x78a5636f, 0x84c87814, 0x8cc70208,
  0x90befffa, 0xa4506ceb, 0xbef9a3f7, 0xc67178f2,
  0xca273ece, 0xd186b8c7, 0xeada7dd6, 0xf57d4f7f,
  0x06f067aa, 0x0a637dc5, 0x113f9804, 0x1b710b35,
  0x28db77f5, 0x32caab7b, 0x3c9ebe0a, 0x431d67c4,
  0x4cc5d4be, 0x597f299c, 0x5fcb6fab, 0x6c44198c,
}
local Kl = {
  0xd728ae22, 0x23ef65cd, 0xec4d3b2f, 0x8189dbbc,
  0xf348b538, 0xb605d019, 0xaf194f9b, 0xda6d8118,
  0xa3030242, 0x45706fbe, 0x4ee4b28c, 0xd5ffb4e2,
  0xf27b896f, 0x3b1696b1, 0x25c71235, 0xcf692694,
  0x9ef14ad2, 0x384f25e3, 0x8b8cd5b5, 0x77ac9c65,
  0x592b0275, 0x6ea6e483, 0xbd41fbd4, 0x831153b5,
  0xee66dfab, 0x2db43210, 0x98fb213f, 0xbeef0ee4,
  0x3da88fc2, 0x930aa725, 0xe003826f, 0x0a0e6e70,
  0x46d22ffc, 0x5c26c926, 0x5ac42aed, 0x9d95b3df,
  0x8baf63de, 0x3c77b2a8, 0x47edaee6, 0x1482353b,
  0x4cf10364, 0xbc423001, 0xd0f89791, 0x0654be30,
  0xd6ef5218, 0x5565a910, 0x5771202a, 0x32bbd1b8,
  0xb8d2d0c8, 0x5141ab53, 0xdf8eeb99, 0xe19b48a8,
  0xc5c95a63, 0xe3418acb, 0x7763e373, 0xd6b2b8a3,
  0x5defb2fc, 0x43172f60, 0xa1f0ab72, 0x1a6439ec,
  0x23631e28, 0xde82bde9, 0xb2c67915, 0xe372532b,
  0xea26619c, 0x21c0c207, 0xcde0eb1e, 0xee6ed178,
  0x72176fba, 0xa2c898a6, 0xbef90dae, 0x131c471b,
  0x23047d84, 0x40c72493, 0x15c9bebc, 0x9c100d4c,
  0xcb3e42b6, 0xfc657e2a, 0x3ad6faec, 0x4a475817,
}
local H0h = { 0x6a09e667, 0xbb67ae85, 0x3c6ef372, 0xa54ff53a, 0x510e527f, 0x9b05688c, 0x1f83d9ab, 0x5be0cd19 }
local H0l = { 0xf3bcc908, 0x84caa73b, 0xfe94f82b, 0x5f1d36f1, 0xade682d1, 0x2b3e6c1f, 0xfb41bd6b, 0x137e2179 }

local M = {}

local function yieldNow()
  os.queueEvent("tsr_yield")
  os.pullEventRaw("tsr_yield")
end

local function compress(Hh, Hl, msg, base)
  local Wh, Wl = {}, {}
  for i = 0, 15 do
    local a, b, c, d, e, f, g, h = sbyte(msg, base + i * 8 + 1, base + i * 8 + 8)
    Wh[i + 1] = ((a * 256 + b) * 256 + c) * 256 + d
    Wl[i + 1] = ((e * 256 + f) * 256 + g) * 256 + h
  end
  for i = 17, 80 do
    local xh, xl = Wh[i - 15], Wl[i - 15]
    local s0h = bxor(bor(rshift(xh, 1), lshift(xl, 31)), bor(rshift(xh, 8), lshift(xl, 24)), rshift(xh, 7))
    local s0l = bxor(bor(rshift(xl, 1), lshift(xh, 31)), bor(rshift(xl, 8), lshift(xh, 24)), bor(rshift(xl, 7), lshift(xh, 25)))
    local yh, yl = Wh[i - 2], Wl[i - 2]
    local s1h = bxor(bor(rshift(yh, 19), lshift(yl, 13)), bor(rshift(yl, 29), lshift(yh, 3)), rshift(yh, 6))
    local s1l = bxor(bor(rshift(yl, 19), lshift(yh, 13)), bor(rshift(yh, 29), lshift(yl, 3)), bor(rshift(yl, 6), lshift(yh, 26)))
    local l = Wl[i - 16] + s0l + Wl[i - 7] + s1l
    local carry = floor(l / MOD)
    Wl[i] = l - carry * MOD
    Wh[i] = (Wh[i - 16] + s0h + Wh[i - 7] + s1h + carry) % MOD
  end
  local ah, al, bh, bl, ch, cl, dh, dl = Hh[1], Hl[1], Hh[2], Hl[2], Hh[3], Hl[3], Hh[4], Hl[4]
  local eh, el, fh, fl, gh, gl, hh, hl = Hh[5], Hl[5], Hh[6], Hl[6], Hh[7], Hl[7], Hh[8], Hl[8]
  for i = 1, 80 do
    local S1h = bxor(bor(rshift(eh, 14), lshift(el, 18)), bor(rshift(eh, 18), lshift(el, 14)), bor(rshift(el, 9), lshift(eh, 23)))
    local S1l = bxor(bor(rshift(el, 14), lshift(eh, 18)), bor(rshift(el, 18), lshift(eh, 14)), bor(rshift(eh, 9), lshift(el, 23)))
    local chh = bxor(band(eh, fh), band(bnot(eh), gh))
    local chl = bxor(band(el, fl), band(bnot(el), gl))
    local l1 = hl + S1l + chl + Kl[i] + Wl[i]
    local c1 = floor(l1 / MOD)
    local t1l = l1 - c1 * MOD
    local t1h = (hh + S1h + chh + Kh[i] + Wh[i] + c1) % MOD
    local S0h = bxor(bor(rshift(ah, 28), lshift(al, 4)), bor(rshift(al, 2), lshift(ah, 30)), bor(rshift(al, 7), lshift(ah, 25)))
    local S0l = bxor(bor(rshift(al, 28), lshift(ah, 4)), bor(rshift(ah, 2), lshift(al, 30)), bor(rshift(ah, 7), lshift(al, 25)))
    local mjh = bxor(band(ah, bh), band(ah, ch), band(bh, ch))
    local mjl = bxor(band(al, bl), band(al, cl), band(bl, cl))
    local l2 = S0l + mjl
    local c2 = floor(l2 / MOD)
    local t2l = l2 - c2 * MOD
    local t2h = (S0h + mjh + c2) % MOD
    hh, hl, gh, gl, fh, fl = gh, gl, fh, fl, eh, el
    local l3 = dl + t1l
    local c3 = floor(l3 / MOD)
    el = l3 - c3 * MOD
    eh = (dh + t1h + c3) % MOD
    dh, dl, ch, cl, bh, bl = ch, cl, bh, bl, ah, al
    local l4 = t1l + t2l
    local c4 = floor(l4 / MOD)
    al = l4 - c4 * MOD
    ah = (t1h + t2h + c4) % MOD
  end
  local vh = { ah, bh, ch, dh, eh, fh, gh, hh }
  local vl = { al, bl, cl, dl, el, fl, gl, hl }
  for i = 1, 8 do
    local l = Hl[i] + vl[i]
    local c = floor(l / MOD)
    Hl[i] = l - c * MOD
    Hh[i] = (Hh[i] + vh[i] + c) % MOD
  end
end

--- SHA-512 of `msg` as a 64-byte binary string. Long inputs yield to the scheduler now and then.
function M.digest(msg)
  local len = #msg
  local Hh, Hl = { table.unpack(H0h) }, { table.unpack(H0l) }
  local bits = len * 8
  msg = msg .. "\128" .. srep("\0", (111 - len) % 128) .. srep("\0", 8) .. schar(
    floor(bits / 72057594037927936) % 256, floor(bits / 281474976710656) % 256, floor(bits / 1099511627776) % 256,
    floor(bits / 4294967296) % 256, floor(bits / 16777216) % 256, floor(bits / 65536) % 256, floor(bits / 256) % 256, bits % 256)
  return M._finish(msg, Hh, Hl)
end

function M._finish(msg, Hh, Hl)
  local blocks = #msg / 128
  for b = 0, blocks - 1 do
    compress(Hh, Hl, msg, b * 128)
    if b % 400 == 399 then yieldNow() end
  end
  local out = {}
  for i = 1, 8 do
    local h, l = Hh[i], Hl[i]
    out[i] = schar(floor(h / 16777216), floor(h / 65536) % 256, floor(h / 256) % 256, h % 256,
      floor(l / 16777216), floor(l / 65536) % 256, floor(l / 256) % 256, l % 256)
  end
  return table.concat(out)
end

--- SHA-512 as 128 lowercase hex characters.
function M.hex(msg)
  return (M.digest(msg):gsub(".", function(c) return sformat("%02x", sbyte(c)) end))
end

return M
